export const ICON_NAMES = Object.keys(ICONS);

export function Icon({ name, size = 20, color, style }) {
  const ic = ICONS[name];
  if (!ic) return null;
  if (ic.node) {
    // 합성(2색) 아이콘 — color prop은 무시하고 고정 색으로 렌더
    return (
      <svg width={size} height={size} viewBox="0 0 20 20" fill="none" style={style} xmlns="http://www.w3.org/2000/svg">
        {ic.node}
      </svg>
    );
  }
  // transform: rotate(중심 10,10 기준) + translate 결합
  const tp = [];
  if (ic.rotate) tp.push(`rotate(${ic.rotate} 10 10)`);
  if (ic.tx || ic.ty) tp.push(`translate(${ic.tx || 0} ${ic.ty || 0})`);
  const t = tp.length ? tp.join(' ') : undefined;
  return (
    <svg width={size} height={size} viewBox={ic.vb || "0 0 20 20"} fill="none" style={style} xmlns="http://www.w3.org/2000/svg">
      <path d={ic.d} transform={t} fill={color || ic.c} fillOpacity={ic.o ?? 1} />
    </svg>
  );
}
